import {CUT_W,CUT_H,exportSpec} from './core.mjs';
const loaded=new Map();
export function loadImage(src){if(loaded.has(src))return loaded.get(src);const p=new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('이미지를 불러오지 못했어요.'));im.src=src;});loaded.set(src,p);p.catch(()=>loaded.delete(src));return p;}
export function forgetImage(src){loaded.delete(src);}
export function cover(ctx,img,x,y,w,h,fit='cover'){const iw=img.naturalWidth||img.width,ih=img.naturalHeight||img.height;const ratio=(fit==='contain'?Math.min:Math.max)(w/iw,h/ih),dw=iw*ratio,dh=ih*ratio;ctx.drawImage(img,x+(w-dw)/2,y+(h-dh)/2,dw,dh);}
export async function backgroundImage(id,backgrounds){return loadImage(backgrounds.find(b=>b.id===id)?.url||'./assets/backgrounds/space.svg');}
export function drawItem(ctx,item,assets){const a=assets.get(item.assetId);if(!a)return;ctx.save();ctx.translate(item.x,item.y);ctx.rotate(item.rotation*Math.PI/180);ctx.scale(item.scale,item.scale);if(item.border){ctx.save();ctx.shadowColor='#fff';ctx.shadowBlur=0;const d=7/item.scale;for(let i=0;i<12;i++){ctx.shadowOffsetX=Math.cos(i*Math.PI/6)*d;ctx.shadowOffsetY=Math.sin(i*Math.PI/6)*d;ctx.drawImage(a.image,-a.w/2,-a.h/2,a.w,a.h);}ctx.restore();}ctx.drawImage(a.image,-a.w/2,-a.h/2,a.w,a.h);ctx.restore();}
export async function drawCut(canvas,cut,assets,backgrounds,{selected=null,placeholder=false}={}){const ctx=canvas.getContext('2d');const bg=await backgroundImage(cut.background,backgrounds);ctx.save();ctx.clearRect(0,0,canvas.width,canvas.height);ctx.scale(canvas.width/CUT_W,canvas.height/CUT_H);ctx.fillStyle='#e7e6fa';ctx.fillRect(0,0,CUT_W,CUT_H);const originals=cut.items.filter(i=>i.kind==='person');if(cut.original&&originals.length){const a=assets.get(originals[0].assetId);if(a?.source)cover(ctx,a.source,0,0,CUT_W,CUT_H);else cover(ctx,bg,0,0,CUT_W,CUT_H,cut.fit);}else cover(ctx,bg,0,0,CUT_W,CUT_H,cut.fit);
ctx.save();ctx.beginPath();ctx.rect(0,0,CUT_W,CUT_H);ctx.clip();for(const item of cut.items){if(cut.original&&item.kind==='person')continue;drawItem(ctx,item,assets);}ctx.restore();
if(placeholder&&!cut.items.length){ctx.fillStyle='#ffffffaa';ctx.beginPath();ctx.arc(600,390,64,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(600,640,150,160,0,Math.PI,0);ctx.fill();ctx.font='600 25px sans-serif';ctx.textAlign='center';ctx.fillStyle='#ffffff';ctx.shadowColor='#121b47';ctx.shadowBlur=7;ctx.fillText('여기에 우리의 순간을 담아요',600,770);ctx.shadowBlur=0;}
if(selected&&!cut.original){const item=cut.items.find(i=>i.id===selected),a=item&&assets.get(item.assetId);if(a){ctx.save();ctx.translate(item.x,item.y);ctx.rotate(item.rotation*Math.PI/180);ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.setLineDash([10,8]);const w=a.w*item.scale,h=a.h*item.scale;ctx.strokeRect(-w/2-12,-h/2-12,w+24,h+24);ctx.restore();}}ctx.restore();}
function fitText(ctx,text,maxWidth,start=54){let size=start;do{ctx.font=`700 ${size}px "Malgun Gothic", sans-serif`;if(ctx.measureText(text).width<=maxWidth)return;}while(--size>24);}
export async function renderProject(project,assets,backgrounds,scale=1,logo=null){await document.fonts.ready;const spec=exportSpec(project.layout);const out=document.createElement('canvas');out.width=Math.round(spec.w*scale);out.height=Math.round(spec.h*scale);const ctx=out.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle=project.frame;ctx.fillRect(0,0,spec.w,spec.h);for(let i=0;i<4;i++){const c=document.createElement('canvas');c.width=CUT_W;c.height=CUT_H;await drawCut(c,project.cuts[i],assets,backgrounds);const rect=spec.cells[i];ctx.drawImage(c,rect.x,rect.y,rect.w,rect.h);c.width=c.height=0;}ctx.fillStyle=contrast(project.frame);ctx.textAlign='center';let y=spec.footerY;const center=spec.w/2;if(logo){const k=Math.min(200/logo.width,70/logo.height);ctx.drawImage(logo,center-logo.width*k/2,y-20,logo.width*k,logo.height*k);y+=75;}fitText(ctx,project.caption,spec.w-200);ctx.fillText(project.caption,center,y+40);ctx.font='32px "Malgun Gothic", sans-serif';ctx.fillText(project.subtitle.slice(0,50),center,y+108);ctx.font='27px "Malgun Gothic", sans-serif';ctx.fillText([project.school,project.date].filter(Boolean).join(' · '),center,y+165);ctx.globalAlpha=.7;ctx.font='21px sans-serif';ctx.fillText('상상네컷 · OUR LITTLE ADVENTURE',center,y+225);ctx.globalAlpha=1;return out;}
export function contrast(hex){const n=hex.replace('#','');const c=[0,2,4].map(i=>parseInt(n.slice(i,i+2),16));return (c[0]*299+c[1]*587+c[2]*114)/1000>165?'#252039':'#ffffff';}
export function makeDecoration(type){const c=document.createElement('canvas');c.width=c.height=180;const x=c.getContext('2d');x.lineJoin='round';x.fillStyle=type==='heart'?'#ff719c':type==='star'?'#ffd966':'#bea7ff';x.strokeStyle='#fff';x.lineWidth=9;x.beginPath();if(type==='heart'){x.moveTo(90,155);x.bezierCurveTo(-10,100,0,20,52,32);x.bezierCurveTo(72,35,84,48,90,60);x.bezierCurveTo(115,0,190,30,153,98);x.bezierCurveTo(140,120,120,139,90,155);}else if(type==='star'){for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?34:75;x.lineTo(90+Math.cos(a)*r,90+Math.sin(a)*r);}x.closePath();}else{x.moveTo(90,10);x.quadraticCurveTo(98,80,170,90);x.quadraticCurveTo(98,98,90,170);x.quadraticCurveTo(82,98,10,90);x.quadraticCurveTo(82,82,90,10);}x.stroke();x.fill();return c;}
